// Exercise static allocator accessor; result is ephemeral and not pooled.
// No inputs; just call and discard.
(void)nlohmann::json::get_allocator();
// Validation: no persistent objects are produced; call should not throw.

// Obtain library metadata as a JSON value (by value) and persist it.
auto meta_j = nlohmann::json::meta();
// Persist into a heap object managed by the fuzzer runtime pool.
nlohmann::json *j = new nlohmann::json(std::move(meta_j));
// Validation: j must be non-null by construction and contains an object with metadata.

// Construct a JSON of a fuzz-chosen type tag.
// Map fuzzed integer into the known value_t domain [0..9] (null, object, array, string, boolean,
// number_integer, number_unsigned, number_float, binary, discarded).
unsigned int raw = *FUZZ_PARAM(unsigned int);
int tag_index = (int)(raw % 10);
// Safely cast to value_t; values beyond the enum range are masked by modulo above.
nlohmann::detail::value_t vt = static_cast<nlohmann::detail::value_t>(tag_index);
// Allocate the JSON with the chosen type.
nlohmann::json *j = new nlohmann::json(vt);
// Validation: j is allocated and owns its storage for structured types; kept for further fuzzing.

// Build a small random byte container and subtype, then construct a binary JSON value.
std::string bytes = FUZZ_PARAM_STR();
// Limit size to keep allocations small.
if (bytes.size() > 1024) { bytes.resize(1024); }
std::vector<std::uint8_t> buf(bytes.begin(), bytes.end());
std::uint8_t subtype = static_cast<std::uint8_t>(*FUZZ_PARAM(unsigned int));
// Create binary JSON value (by value) and persist it.
auto bj = nlohmann::json::binary(buf, subtype);
nlohmann::json *j = new nlohmann::json(std::move(bj));
// Validation: j now holds a binary value; pointer is non-null and owned by the pool.

// Create an empty array via the factory (avoids initializer validation errors) and persist it.
auto arr = nlohmann::json::array({});
nlohmann::json *j = new nlohmann::json(std::move(arr));
// Validation: j contains an array; pointer is valid.

// Create an empty object via the factory (no invalid initializer pairs) and persist it.
auto obj = nlohmann::json::object({});
nlohmann::json *j = new nlohmann::json(std::move(obj));
// Validation: j contains an object; pointer is valid.

// Prepare a fuzz-generated RHS JSON value to exercise copy-and-swap assignment.
// Use a small parsed document to vary structure.
std::string s = FUZZ_PARAM_STR();
if (s.size() > 1024) { s.resize(1024); }
// Try to parse; if invalid, fall back to a primitive to ensure a valid JSON value exists.
nlohmann::json rhs;
try {
    rhs = nlohmann::json::parse(s, /*cb*/nullptr, /*allow_exceptions*/false);
    if (rhs.is_discarded()) {
        // fallback to a primitive boolean/integer
        if ((*FUZZ_PARAM(unsigned int) & 1U) != 0U) rhs = true; else rhs = (std::int64_t)(*FUZZ_PARAM(unsigned int));
    }
} catch (...) {
    rhs = nullptr;
}
// Perform assignment on the input object.
*j = rhs; // invokes operator=(basic_json other) via copy/move
// Keep j alive as output for subsequent stubs.
// Validation: j remains valid; operator= should leave a well-formed JSON state.

// Destroy the JSON object to exercise the destructor and release owned memory.
// After deletion, we must not return j to the pool.
delete j;
// Validation: no outputs returned; avoids double free or use-after-free.

// Serialize with random pretty-print parameters; keep result ephemeral.
int indent = ((*FUZZ_PARAM(unsigned int)) % 10) - 1; // -1 (compact) to 8
char indent_char = static_cast<char>(32 + (*FUZZ_PARAM(unsigned int) % 95)); // printable ASCII
bool ensure_ascii = ((*FUZZ_PARAM(unsigned int)) & 1U) != 0U;
(void)j->dump(indent, indent_char, ensure_ascii);
// Return j to the pool; the string result is transient.
// Validation: call should succeed for any JSON; object lifetime preserved.

// Query the type; result is ephemeral metadata.
(void)j->type();
// Keep j for future use.
// Validation: non-throwing, preserves j.

// Predicate query; ignore return value but exercise branch paths.
(void)j->is_primitive();
// Preserve the JSON object.
// Validation: call is noexcept; j remains valid.

(void)j->is_structured();
// Keep j alive.
// Validation: noexcept predicate; no state changes.

(void)j->is_null();
// Preserve j.
// Validation: no side effects.

(void)j->is_boolean();
// Preserve j.
// Validation: no side effects.

(void)j->is_number();
// Preserve j.
// Validation: no side effects.

(void)j->is_number_integer();
// Preserve j.
// Validation: no side effects.

(void)j->is_number_unsigned();
// Preserve j.
// Validation: no side effects.

(void)j->is_number_float();
// Preserve j.
// Validation: no side effects.

(void)j->is_object();
// Preserve j.
// Validation: no side effects.

(void)j->is_array();
// Preserve j.
// Validation: no side effects.

// Query predicate; exercise branch, preserve object.
(void)j->is_string();
// Validation: noexcept and side-effect free; j remains valid.

// Use implicit conversion to value_t and ignore the result.
(void)static_cast<nlohmann::json::value_t>(*j);
// Validation: constexpr/noexcept by API; j unchanged.

// Try obtaining pointers to various internal representations.
// All calls are noexcept and return nullptr on type mismatch.
(void)j->get_ptr<nlohmann::json::array_t*>();
(void)j->get_ptr<nlohmann::json::object_t*>();
(void)j->get_ptr<nlohmann::json::string_t*>();
(void)j->get_ptr<nlohmann::json::boolean_t*>();
(void)j->get_ptr<nlohmann::json::number_integer_t*>();
(void)j->get_ptr<nlohmann::json::number_unsigned_t*>();
(void)j->get_ptr<nlohmann::json::number_float_t*>();
(void)j->get_ptr<nlohmann::json::binary_t*>();
// Validation: covers multiple branches; j preserved.

// Invoke get<ValueType>() with a type matching the current JSON to avoid exceptions.
// This exercises the conversion machinery without relying on throwing behavior.
if (j->is_string()) {
    (void)j->get<nlohmann::json::string_t>();
} else if (j->is_boolean()) {
    (void)j->get<nlohmann::json::boolean_t>();
} else if (j->is_number_integer()) {
    (void)j->get<nlohmann::json::number_integer_t>();
} else if (j->is_number_unsigned()) {
    (void)j->get<nlohmann::json::number_unsigned_t>();
} else if (j->is_number_float()) {
    (void)j->get<nlohmann::json::number_float_t>();
} else if (j->is_array()) {
    (void)j->get<nlohmann::json::array_t>();
} else if (j->is_object()) {
    (void)j->get<nlohmann::json::object_t>();
} else if (j->is_binary()) {
    (void)j->get<nlohmann::json::binary_t>();
} else {
    // null or discarded cannot be obtained as a value directly; bail per constraints.
    FUZZ_BAIL();
}
// Validation: get() called with compatible type; j preserved.

// Use get_to into an existing value matching the current JSON type.
if (j->is_string()) {
    nlohmann::json::string_t s; (void)j->get_to(s);
} else if (j->is_boolean()) {
    nlohmann::json::boolean_t b{}; (void)j->get_to(b);
} else if (j->is_number_integer()) {
    nlohmann::json::number_integer_t v{}; (void)j->get_to(v);
} else if (j->is_number_unsigned()) {
    nlohmann::json::number_unsigned_t v{}; (void)j->get_to(v);
} else if (j->is_number_float()) {
    nlohmann::json::number_float_t v{}; (void)j->get_to(v);
} else if (j->is_array()) {
    nlohmann::json::array_t arr; (void)j->get_to(arr);
} else if (j->is_object()) {
    nlohmann::json::object_t obj; (void)j->get_to(obj);
} else if (j->is_binary()) {
    nlohmann::json::binary_t bin; (void)j->get_to(bin);
} else {
    // null or discarded cannot be deserialized meaningfully via get_to
    FUZZ_BAIL();
}
// Validation: deserialization succeeds for matching types; j preserved.

// Return a reference to the exact internal type. This requires exact type matching.
if (j->is_string()) {
    (void)j->get_ref<nlohmann::json::string_t&>();
} else if (j->is_boolean()) {
    (void)j->get_ref<nlohmann::json::boolean_t&>();
} else if (j->is_number_integer()) {
    (void)j->get_ref<nlohmann::json::number_integer_t&>();
} else if (j->is_number_unsigned()) {
    (void)j->get_ref<nlohmann::json::number_unsigned_t&>();
} else if (j->is_number_float()) {
    (void)j->get_ref<nlohmann::json::number_float_t&>();
} else if (j->is_array()) {
    (void)j->get_ref<nlohmann::json::array_t&>();
} else if (j->is_object()) {
    (void)j->get_ref<nlohmann::json::object_t&>();
} else if (j->is_binary()) {
    (void)j->get_ref<nlohmann::json::binary_t&>();
} else {
    // null or discarded have no reference type available
    FUZZ_BAIL();
}
// Validation: get_ref only called with valid ReferenceType; j preserved.

// Exercise implicit/explicit conversion operators to matching native types.
if (j->is_boolean()) {
    (void)static_cast<nlohmann::json::boolean_t>(*j);
} else if (j->is_number_integer()) {
    (void)static_cast<nlohmann::json::number_integer_t>(*j);
} else if (j->is_number_unsigned()) {
    (void)static_cast<nlohmann::json::number_unsigned_t>(*j);
} else if (j->is_number_float()) {
    (void)static_cast<nlohmann::json::number_float_t>(*j);
} else if (j->is_string()) {
    (void)static_cast<nlohmann::json::string_t>(*j);
} else if (j->is_array()) {
    // Convert to array_t only if type matches; operator ValueType delegates to get<ValueType>()
    (void)j->get<nlohmann::json::array_t>();
} else if (j->is_object()) {
    (void)j->get<nlohmann::json::object_t>();
} else if (j->is_binary()) {
    (void)j->get<nlohmann::json::binary_t>();
} else {
    // null/discarded not convertible to value types here
    FUZZ_BAIL();
}
// Validation: conversions used only when semantically valid; j preserved.

// Enforce: must be a binary JSON, otherwise type_error.302
if (!j->is_binary()) { FUZZ_BAIL(); }
(void)j->get_binary();
// Validation: requirement enforced; j preserved.

// Enforce: must be an array and index in range.
if (!j->is_array()) { FUZZ_BAIL(); }
auto sz = j->size();
if (sz == 0) { FUZZ_BAIL(); }
// Choose a valid index within bounds.
std::size_t idx = static_cast<std::size_t>(*FUZZ_PARAM(unsigned int) % sz);
(void)j->at(idx);
// Validation: bounds respected; j preserved.

