import json
import random
import string
from typing import List, Dict, Any

# Strategy:
# - Produce UTF-8 JSON text that is valid and exercises many library features.
# - The fuzzer stubs mainly feed FUZZ_PARAM_STR into nlohmann::json::parse, operator>>,
#   accept, and sax_parse. Valid JSON increases coverage of comparisons and parsing paths.
# - We generate a mixture of objects, arrays, strings, numbers, booleans, null, and nested
#   structures. We sometimes include edge cases like large/small numbers, unicode strings,
#   escaped characters, empty containers, and varied nesting/length.
# - Ensure output is <= 4096 bytes.

SAFE_ASCII = [c for c in string.printable if c not in "\x0b\x0c\x0b\x0c"]

def _rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))

def _rand_int(r: random.Random) -> int:
    # Mix of small and large magnitudes, positive/negative
    choices = [
        0, 1, -1, 42, -42, 127, 128, 255, 256, 1024, -1024,
        2**31 - 1, -2**31, 2**63 - 1, -2**63 + 1
    ]
    if _rand_bool(r):
        return r.choice(choices)
    # random within a range
    mag_choice = r.choice([8, 16, 24, 31, 40, 53, 63])
    val = r.randrange(-(1 << mag_choice), (1 << mag_choice))
    return int(val)

def _rand_float(r: random.Random) -> float:
    # Include special magnitudes
    special = [0.0, -0.0, 1.0, -1.0, 3.141592653589793, 1e-300, 1e300, 1e-10, -1e-10]
    if r.random() < 0.5:
        return r.choice(special)
    # random normal-ish float
    base = r.uniform(-1e6, 1e6)
    scale = 10 ** r.randint(-12, 12)
    return float(base * scale)

def _rand_unicode_str(r: random.Random, min_len=0, max_len=64) -> str:
    # Mix ASCII, escaped sequences, and some unicode ranges
    length = r.randint(min_len, max_len)
    parts: List[str] = []
    for _ in range(length):
        t = r.random()
        if t < 0.65:
            parts.append(r.choice(SAFE_ASCII))
        elif t < 0.80:
            # Basic Latin-1 supplement
            parts.append(chr(r.randint(0x00A0, 0x00FF)))
        elif t < 0.93:
            # BMP general
            parts.append(chr(r.randint(0x0100, 0x07FF)))
        else:
            # a few emoji/surrogates-safe code points (non-surrogate)
            parts.append(chr(r.randint(0x1F300, 0x1F6FF)))
    s = ''.join(parts)
    # Inject some explicit escapes to stress serializer/parser
    escapes = ['\\\"', '\\\\', '\\/','\\b','\\f','\\n','\\r','\\t']
    if s and r.random() < 0.4:
        pos = r.randrange(0, len(s))
        s = s[:pos] + r.choice(escapes) + s[pos:]
    return s

def _rand_binary_base64(r: random.Random, max_len=64) -> str:
    # Represent binary as base64-like string to keep valid JSON
    alphabet = string.ascii_letters + string.digits + '+/='
    n = r.randint(0, max_len)
    return ''.join(r.choice(alphabet) for _ in range(n))

def _make_value(r: random.Random, depth: int) -> Any:
    if depth <= 0:
        kind = r.choice(['null','bool','int','float','string'])
    else:
        kind = r.choices(
            population=['null','bool','int','float','string','array','object'],
            weights=[1, 2, 3, 3, 4, 3, 3], k=1
        )[0]

    if kind == 'null':
        return None
    if kind == 'bool':
        return _rand_bool(r)
    if kind == 'int':
        return _rand_int(r)
    if kind == 'float':
        # Use a float, but occasionally wrap as string to keep numeric-like text
        return _rand_float(r)
    if kind == 'string':
        # Occasionally produce structured-looking strings
        base = _rand_unicode_str(r, 0, r.randint(4, 80))
        if r.random() < 0.2:
            # JSON pointer-ish
            base = '/' + '/'.join(_rand_unicode_str(r, 0, 6) for _ in range(r.randint(0, 5)))
        if r.random() < 0.2:
            # Base64-ish intended for binary fields
            base = _rand_binary_base64(r, 48)
        return base
    if kind == 'array':
        size = r.randint(0, 12)
        return [_make_value(r, depth - 1) for _ in range(size)]
    if kind == 'object':
        obj: Dict[str, Any] = {}
        # Include a variety of keys including with slashes/tilde to hit pointer-escape logic later
        size = r.randint(0, 12)
        for _ in range(size):
            key_type = r.random()
            if key_type < 0.6:
                key = _rand_unicode_str(r, 0, 16)
            elif key_type < 0.8:
                key = 'key_' + str(r.randint(0, 1000))
            else:
                # keys that look like JSON Pointer tokens
                raw = _rand_unicode_str(r, 0, 8)
                key = raw.replace('~', '~0').replace('/', '~1')
            # ensure unique keys
            if key in obj:
                key = key + '_' + str(r.randint(0, 9999))
            # special fields to trigger binary/patch/merge paths if stubs add later
            if r.random() < 0.1:
                obj[key] = {"sub": _make_value(r, depth - 1)}
            else:
                obj[key] = _make_value(r, depth - 1)
        # Occasionally add fields that are meaningful for JSON Patch-like structures
        if r.random() < 0.25:
            obj.setdefault("op", r.choice(["add","remove","replace","move","copy","test"]))
            obj.setdefault("path", "/" + "/".join("p"+str(r.randint(0,3)) for _ in range(r.randint(0,3))))
            if obj["op"] in ("add","replace","test") and r.random() < 0.7:
                obj.setdefault("value", _make_value(r, depth - 1))
            if obj["op"] in ("move","copy"):
                obj.setdefault("from", "/src/"+str(r.randint(0,3)))
        return obj
    # Fallback
    return None

def _make_top_level(r: random.Random) -> Any:
    # Mix between object, array, and primitive
    choose = r.random()
    if choose < 0.45:
        # Object with metadata-like fields to hit comparisons and dumps
        obj: Dict[str, Any] = {
            "name": _rand_unicode_str(r, 3, 24),
            "version": "%d.%d.%d" % (r.randint(0,9), r.randint(0,9), r.randint(0,9)),
            "ok": _rand_bool(r),
            "count": _rand_int(r),
            "ratio": _rand_float(r),
            "tags": [_rand_unicode_str(r, 0, 10) for _ in range(r.randint(0, 6))],
            "data_b64": _rand_binary_base64(r, 64),
            "nested": _make_value(r, 3),
        }
        # Sometimes add empty containers and boundary strings
        if r.random() < 0.5:
            obj["empty_obj"] = {}
        if r.random() < 0.5:
            obj["empty_arr"] = []
        if r.random() < 0.4:
            obj["unicode"] = "こんにちは🌏🚀"
        return obj
    elif choose < 0.8:
        # Array mixture
        arr_len = r.randint(0, 16)
        return [_make_value(r, 3) for _ in range(arr_len)]
    else:
        # Primitive
        return _make_value(r, 0)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Generate a few variants and pick one with size under limit and decent complexity
    for _ in range(5):
        val = _make_top_level(r)
        # Use separators to keep output compact; ensure_ascii false to keep unicode
        try:
            s = json.dumps(val, ensure_ascii=False, separators=(',', ':'))
        except Exception:
            # If serialization somehow fails, fallback to a simple primitive
            s = json.dumps({"fallback": True, "n": 1})
        if len(s.encode('utf-8')) <= 4096:
            return s.encode('utf-8')
    # Final fallback: truncate if somehow exceeded (should not usually happen)
    s = json.dumps(_make_top_level(r), ensure_ascii=False, separators=(',', ':'))
    b = s.encode('utf-8')
    return b[:4096]

import json, random, struct, string

# Generator for inputs targeting nlohmann::json fuzzer stubs that use FUZZ_PARAM_STR/filename
# We craft valid and interesting JSON text or binary-like blobs tailored to each stub usage.
# The fuzzers primarily consume arbitrary strings which are later:
# - used as JSON object keys (find/count/contains/emplace/update/merge_patch)
# - used as byte buffers for from_bjdata/from_bson
# - used as general strings for ADL to_json case 4
# Therefore, producing small JSON documents with varied structures and
# BSON/BJData-looking prefixes will exercise different code paths.

MAX_LEN = 4096

ASCII = string.ascii_letters + string.digits + "_-:/\\."


def _rand(r, n):
    return r.randrange(n)


def _rand_ascii(r, lo=1, hi=16):
    n = r.randint(lo, hi)
    return ''.join(r.choice(ASCII) for _ in range(n))


def _rand_utf8(r, lo=1, hi=16):
    n = r.randint(lo, hi)
    out = []
    for _ in range(n):
        t = r.random()
        if t < 0.7:
            out.append(chr(r.randint(0x20, 0x7E)))
        elif t < 0.85:
            out.append(chr(r.randint(0x00A0, 0x07FF)))
        elif t < 0.97:
            out.append(chr(r.randint(0x0800, 0xD7FF)))
        else:
            # include some emoji/supplementary
            out.append(chr(r.randint(0x1F300, 0x1FAFF)))
    return ''.join(out)


def _json_scalar(r):
    kind = _rand(r, 7)
    if kind == 0:
        return None
    if kind == 1:
        return r.choice([True, False])
    if kind == 2:
        return r.randint(-2**31, 2**31 - 1)
    if kind == 3:
        # unsigned-like value that still fits JSON number
        return r.randint(0, 2**32 - 1)
    if kind == 4:
        # float, include special magnitudes serialized as JSON numbers
        val = r.uniform(-1e6, 1e6)
        return round(val, r.randint(0, 6))
    if kind == 5:
        return _rand_ascii(r, 0, 24)
    return _rand_utf8(r, 0, 16)


def _json_object_with_keys(r, key_count):
    obj = {}
    for _ in range(key_count):
        # keys relevant for find/count/contains/emplace/update/merge_patch
        key_type = _rand(r, 5)
        if key_type == 0:
            k = _rand_ascii(r, 1, 16)
        elif key_type == 1:
            k = _rand_utf8(r, 1, 16)
        elif key_type == 2:
            # include JSON Pointer-like segments
            parts = [_rand_ascii(r, 1, 6) for _ in range(r.randint(1, 3))]
            k = '/'.join(parts)
        elif key_type == 3:
            # include dots for BSON-like field names
            k = '.'.join(_rand_ascii(r, 1, 6) for _ in range(r.randint(1, 3)))
        else:
            # include spaces and punctuation
            k = (_rand_ascii(r, 1, 6) + ' ' + _rand_ascii(r, 1, 6))[:16]
        # ensure uniqueness
        if k in obj:
            k += str(r.randint(0, 99))
        # values: mix scalar/array/object
        v_kind = _rand(r, 4)
        if v_kind == 0:
            obj[k] = _json_scalar(r)
        elif v_kind == 1:
            obj[k] = [_json_scalar(r) for _ in range(r.randint(0, 6))]
        elif v_kind == 2:
            obj[k] = { _rand_ascii(r,1,8): _json_scalar(r) for _ in range(r.randint(0, 4)) }
        else:
            obj[k] = [_json_scalar(r), { _rand_ascii(r,1,6): _json_scalar(r) }]
    return obj


def _build_json_text(r):
    # Build varied root JSON to cover structured/primitive cases used by stubs
    root_kind = _rand(r, 5)
    if root_kind == 0:
        j = _json_object_with_keys(r, r.randint(1, 6))
    elif root_kind == 1:
        j = [ _json_scalar(r) for _ in range(r.randint(0, 8)) ]
        # include nested object occasionally
        if r.random() < 0.6:
            j.append(_json_object_with_keys(r, r.randint(1, 4)))
    elif root_kind == 2:
        j = _json_scalar(r)
    elif root_kind == 3:
        # object with overlapping-looking keys to exercise update/merge behavior
        base = _json_object_with_keys(r, r.randint(2, 5))
        # add keys that may collide when truncated in fuzz stub (<=16/32/64)
        for _ in range(r.randint(1, 3)):
            kk = (_rand_ascii(r, 8, 24))[:32]
            base[kk] = _json_scalar(r)
        j = base
    else:
        # object with boolean/number values for branch variety
        j = { _rand_ascii(r,1,12): r.randint(-10, 10) for _ in range(r.randint(1, 6)) }
        j[_rand_ascii(r,1,12)] = r.choice([True, False])
    try:
        s = json.dumps(j, ensure_ascii=False, separators=(',', ':'))
    except Exception:
        # Fallback simple object
        s = '{"k":1}'
    return s.encode('utf-8')


def _build_bson_like(r):
    # Construct a minimal valid BSON document (little endian) to exercise from_bson
    # BSON format: int32 totalLen, list of elements, 0x00 terminator
    # We'll include a few simple types: int32, string, bool, nested document.
    buf = bytearray()
    elems = bytearray()

    def cstr(b):
        return b + b"\x00"

    def put_string(name, s):
        elems.extend(b"\x02")  # type string
        elems.extend(cstr(name))
        sb = s.encode('utf-8')
        elems.extend(struct.pack('<i', len(sb) + 1))
        elems.extend(sb)
        elems.extend(b"\x00")

    def put_int32(name, v):
        elems.extend(b"\x10")  # int32
        elems.extend(cstr(name))
        elems.extend(struct.pack('<i', v))

    def put_bool(name, v):
        elems.extend(b"\x08")
        elems.extend(cstr(name))
        elems.extend(b"\x01" if v else b"\x00")

    def put_document(name, inner_builder):
        elems.extend(b"\x03")  # embedded document
        elems.extend(cstr(name))
        inner = inner_builder()
        elems.extend(inner)

    # build inner doc
    def inner_doc():
        inner_e = bytearray()
        # one int32 field
        inner_e.extend(b"\x10" + cstr(b"x") + struct.pack('<i', r.randint(-1000, 1000)))
        inner_e.extend(b"\x00")
        total = struct.pack('<i', len(inner_e) + 4)
        return total + inner_e

    # add fields with bounded names to match fuzzer key caps (<=64 etc.)
    put_string(b"name", _rand_utf8(r, 1, 12))
    put_int32(b"n", r.randint(-2**31, 2**31-1))
    put_bool(b"flag", r.choice([True, False]))
    if r.random() < 0.7:
        put_document(b"obj", inner_doc)

    elems.extend(b"\x00")
    total_len = struct.pack('<i', len(elems) + 4)
    buf.extend(total_len)
    buf.extend(elems)
    return bytes(buf)


def _build_bjdata_like(r):
    # Build small valid UBJSON/BJData-like sequence that parser can often accept
    # We will emit: { 'a': int8, 'b': string, 'c': array of small ints }
    out = bytearray()
    def add_obj():
        out.extend(b"{")
        # key 'a': int8 42 => i*
        out.extend(b"a")
        out.extend(b"i*")
        # key 'b': string => S[length][data]
        out.extend(b"b")
        s = _rand_utf8(r, 0, 8).encode('utf-8')
        out.extend(b"S")
        out.extend(b"i")
        out.extend(struct.pack('>b', len(s)))
        out.extend(s)
        # key 'c': array of ints => [#][count]i values
        out.extend(b"c")
        out.extend(b"[")
        arr_len = r.randint(0, 5)
        out.extend(b"#i")
        out.extend(struct.pack('>b', arr_len))
        for _ in range(arr_len):
            out.extend(b"i")
            out.extend(struct.pack('>b', r.randint(-64, 63)))
        out.extend(b"]")
        out.extend(b"}")
    add_obj()
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    mode = r.randrange(6)
    if mode == 0:
        # JSON text geared toward object operations and merge/update
        data = _build_json_text(r)
    elif mode == 1:
        # BSON-like binary for from_bson
        data = _build_bson_like(r)
    elif mode == 2:
        # BJData/UBJSON-like binary for from_bjdata
        data = _build_bjdata_like(r)
    elif mode == 3:
        # Plain string for keys (FUZZ_PARAM_STR), varied length
        s = _rand_utf8(r, 0, 64)
        data = s.encode('utf-8')
    elif mode == 4:
        # Compact JSON object with short keys and mixed values
        obj = _json_object_with_keys(r, r.randint(2, 6))
        data = json.dumps(obj, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    else:
        # JSON array with numbers/booleans/strings to hit to_json serialization
        arr = []
        for _ in range(r.randint(0, 8)):
            arr.append(_json_scalar(r))
        data = json.dumps(arr, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

    if len(data) > MAX_LEN:
        data = data[:MAX_LEN]
    return data

import random
import struct
from typing import List

# This generator targets inputs consumed as arbitrary binary bytes by fuzz stubs for:
# - nlohmann::json::binary(buf, subtype)
# - nlohmann::json::from_cbor/msgpack/ubjson/bjdata/bson
# The fuzzer obtains a std::string from FUZZ_PARAM_STR() and converts it to bytes.
# We therefore return a bytes object representing interesting, valid binary payloads
# for these formats. We keep size <= 1024 (well under the 4096 cap).

MAX_OUT = 1024

# ---------- Helpers for constructing minimal valid payloads for each format ----------

def _rand_rng(seed: int) -> random.Random:
    return random.Random(seed)

# CBOR minimal encoders (subset sufficient for valid decoding)
# CBOR major types: 0=unsigned,1=neg,2=bytes,3=text,4=array,5=map,6=tag,7=simple/float

def _cbor_uint(n: int) -> bytes:
    assert n >= 0
    if n < 24:
        return bytes([0x00 | n])
    if n <= 0xFF:
        return bytes([0x18, n])
    if n <= 0xFFFF:
        return bytes([0x19]) + struct.pack('>H', n)
    if n <= 0xFFFFFFFF:
        return bytes([0x1a]) + struct.pack('>I', n)
    return bytes([0x1b]) + struct.pack('>Q', n)


def _cbor_negint(n: int) -> bytes:
    # encodes negative integer x as -1 - x
    assert n < 0
    ui = -1 - n
    if ui < 24:
        return bytes([0x20 | ui])
    if ui <= 0xFF:
        return bytes([0x38, ui])
    if ui <= 0xFFFF:
        return bytes([0x39]) + struct.pack('>H', ui)
    if ui <= 0xFFFFFFFF:
        return bytes([0x3a]) + struct.pack('>I', ui)
    return bytes([0x3b]) + struct.pack('>Q', ui)


def _cbor_bytes(b: bytes) -> bytes:
    l = len(b)
    prefix = None
    if l < 24:
        prefix = bytes([0x40 | l])
    elif l <= 0xFF:
        prefix = bytes([0x58, l])
    elif l <= 0xFFFF:
        prefix = bytes([0x59]) + struct.pack('>H', l)
    else:
        prefix = bytes([0x5a]) + struct.pack('>I', l)
    return prefix + b


def _cbor_text(s: str) -> bytes:
    b = s.encode('utf-8')
    l = len(b)
    if l < 24:
        prefix = bytes([0x60 | l])
    elif l <= 0xFF:
        prefix = bytes([0x78, l])
    elif l <= 0xFFFF:
        prefix = bytes([0x79]) + struct.pack('>H', l)
    else:
        prefix = bytes([0x7a]) + struct.pack('>I', l)
    return prefix + b


def _cbor_array(items: List[bytes]) -> bytes:
    l = len(items)
    if l < 24:
        head = bytes([0x80 | l])
    elif l <= 0xFF:
        head = bytes([0x98, l])
    elif l <= 0xFFFF:
        head = bytes([0x99]) + struct.pack('>H', l)
    else:
        head = bytes([0x9a]) + struct.pack('>I', l)
    return head + b''.join(items)


def _cbor_map(entries: List[bytes]) -> bytes:
    # entries are concatenated pairs: key, value
    pairs = len(entries) // 2
    if pairs < 24:
        head = bytes([0xA0 | pairs])
    elif pairs <= 0xFF:
        head = bytes([0xB8, pairs])
    elif pairs <= 0xFFFF:
        head = bytes([0xB9]) + struct.pack('>H', pairs)
    else:
        head = bytes([0xBA]) + struct.pack('>I', pairs)
    return head + b''.join(entries)


def _build_valid_cbor(rng: random.Random) -> bytes:
    choice = rng.randrange(6)
    if choice == 0:
        return _cbor_uint(rng.randrange(0, 1 << 16))
    if choice == 1:
        return _cbor_negint(-rng.randrange(1, 1 << 8))
    if choice == 2:
        return _cbor_text(rng.choice(["", "hello", "π", "emoji 😊", "nested"]))
    if choice == 3:
        # small array with mixed types
        items = [
            _cbor_uint(rng.randrange(0, 100)),
            _cbor_text("a" * rng.randrange(0, 5)),
            _cbor_bytes(rng.randbytes(rng.randrange(0, 8)))
        ]
        return _cbor_array(items)
    if choice == 4:
        # small map
        entries = [
            _cbor_text("k"), _cbor_uint(1),
            _cbor_text("s"), _cbor_text("v"),
        ]
        return _cbor_map(entries)
    # bytes
    return _cbor_bytes(rng.randbytes(rng.randrange(0, 16)))

# MessagePack minimal encoders (subset)

def _mp_fixint(n: int) -> bytes:
    if -32 <= n <= 127:
        return struct.pack('b', n) if n < 0 else bytes([n])
    if 0 <= n <= 0xFF:
        return b"\xcc" + bytes([n])
    if -128 <= n <= 127:
        return b"\xd0" + struct.pack('b', n)
    if 0 <= n <= 0xFFFF:
        return b"\xcd" + struct.pack('>H', n)
    return b"\xce" + struct.pack('>I', max(0, n))


def _mp_str(s: str) -> bytes:
    b = s.encode('utf-8')
    l = len(b)
    if l <= 31:
        return bytes([0xA0 | l]) + b
    if l <= 0xFF:
        return b"\xD9" + bytes([l]) + b
    return b"\xDA" + struct.pack('>H', l) + b


def _mp_bin(b: bytes) -> bytes:
    l = len(b)
    if l <= 0xFF:
        return b"\xC4" + bytes([l]) + b
    return b"\xC5" + struct.pack('>H', l) + b


def _mp_array(items: List[bytes]) -> bytes:
    l = len(items)
    if l <= 15:
        head = bytes([0x90 | l])
    else:
        head = b"\xDC" + struct.pack('>H', l)
    return head + b''.join(items)


def _mp_map(pairs: List[bytes]) -> bytes:
    n = len(pairs) // 2
    if n <= 15:
        head = bytes([0x80 | n])
    else:
        head = b"\xDE" + struct.pack('>H', n)
    return head + b''.join(pairs)


def _build_valid_msgpack(rng: random.Random) -> bytes:
    choice = rng.randrange(5)
    if choice == 0:
        return _mp_fixint(rng.randrange(-20, 200))
    if choice == 1:
        return _mp_str(rng.choice(["", "hello", "世界", "json"]))
    if choice == 2:
        return _mp_bin(rng.randbytes(rng.randrange(0, 16)))
    if choice == 3:
        arr = [
            _mp_fixint(rng.randrange(0, 10)),
            _mp_str("a" * rng.randrange(0, 5))
        ]
        return _mp_array(arr)
    pairs = [
        _mp_str("k"), _mp_fixint(1),
        _mp_str("s"), _mp_str("v"),
    ]
    return _mp_map(pairs)

# UBJSON/BJData minimal encoders
# We'll produce simple, valid subsets: types with length-prefixed containers.

def _ubj_int(n: int) -> bytes:
    # Prefer int32 if fits; UBJSON markers: i=int32, l=int64, U=uint8
    if 0 <= n <= 255:
        return b"U" + bytes([n])
    if -2147483648 <= n <= 2147483647:
        return b"i" + struct.pack('>i', n)
    return b"l" + struct.pack('>q', n)


def _ubj_str(s: str) -> bytes:
    b = s.encode('utf-8')
    return b"S" + b"i" + struct.pack('>i', len(b)) + b


def _ubj_bin(b: bytes) -> bytes:
    # UBJSON binary not standard; BJData supports 'B' typed with length
    return b"Bi" + struct.pack('>i', len(b)) + b


def _ubj_array(items: List[bytes]) -> bytes:
    # Typed array with count for compactness: [ $<type> #<count> <payload> ]
    # For simplicity use untyped with explicit delimiters: [ <items> ]
    return b"[" + b"".join(items) + b"]"


def _ubj_object(pairs: List[bytes]) -> bytes:
    # Untyped object with name/value pairs terminated by '}'
    return b"{" + b"".join(pairs) + b"}"


def _ubj_kv(key: str, val: bytes) -> bytes:
    return _ubj_str(key) + val


def _build_valid_ubjson(rng: random.Random, bjdata: bool = False) -> bytes:
    choice = rng.randrange(5)
    if choice == 0:
        return _ubj_int(rng.randrange(-1000, 1000))
    if choice == 1:
        return _ubj_str(rng.choice(["", "hello", "ubj", "数据"]))
    if choice == 2:
        data = rng.randbytes(rng.randrange(0, 16))
        return _ubj_bin(data) if bjdata else _ubj_array([_ubj_int(b) for b in data[:4]])
    if choice == 3:
        arr = [_ubj_int(1), _ubj_str("x")]
        return _ubj_array(arr)
    pairs = [
        _ubj_kv("a", _ubj_int(1)),
        _ubj_kv("b", _ubj_str("v")),
    ]
    return _ubj_object(pairs)

# Minimal BSON document encoder: <int32 length> <elements> 0x00
# Elements: type(1) cstring key NUL then value.
# We'll build {"k": <int32>} and optionally add a string.

def _bson_cstring(s: str) -> bytes:
    return s.encode('utf-8') + b"\x00"


def _bson_int32(key: str, val: int) -> bytes:
    return b"\x10" + _bson_cstring(key) + struct.pack('<i', int(val))


def _bson_string(key: str, s: str) -> bytes:
    b = s.encode('utf-8')
    # length includes trailing NUL
    return b"\x02" + _bson_cstring(key) + struct.pack('<i', len(b) + 1) + b + b"\x00"


def _bson_doc(elements: List[bytes]) -> bytes:
    body = b"".join(elements) + b"\x00"
    total_len = len(body) + 4
    return struct.pack('<i', total_len) + body


def _build_valid_bson(rng: random.Random) -> bytes:
    elems = [_bson_int32("n", rng.randrange(-1000, 1000))]
    if rng.random() < 0.5:
        elems.append(_bson_string("s", rng.choice(["", "hi", "世界"])))
    return _bson_doc(elems)

# Binary JSON value payload: any bytes sequence is valid, but we choose varied lengths/content.

def _build_arbitrary_bytes(rng: random.Random, max_len: int = 64) -> bytes:
    patterns = []
    # Repeated pattern
    p = rng.choice([b"\x00", b"\xff", b"AB", b"\x01\x02\x03\x04"]) * rng.randrange(1, 16)
    patterns.append(p)
    # Random bytes
    patterns.append(rng.randbytes(rng.randrange(0, max_len)))
    # Ascending
    l = rng.randrange(0, max_len)
    patterns.append(bytes([i % 256 for i in range(l)]))
    return rng.choice(patterns)[:max_len]

# ---------- Master builder selecting a format and composing the output ----------

def _choose_one(rng: random.Random) -> bytes:
    # Formats: 0=CBOR,1=MessagePack,2=UBJSON,3=BJData,4=BSON,5=Binary blob
    fmt = rng.randrange(6)
    if fmt == 0:
        return _build_valid_cbor(rng)
    if fmt == 1:
        return _build_valid_msgpack(rng)
    if fmt == 2:
        return _build_valid_ubjson(rng, bjdata=False)
    if fmt == 3:
        return _build_valid_ubjson(rng, bjdata=True)
    if fmt == 4:
        return _build_valid_bson(rng)
    return _build_arbitrary_bytes(rng, max_len=128)

# Sometimes prepend or append extra valid items to exercise streaming/concatenation tolerant decoders.

def _maybe_concat(rng: random.Random, base: bytes) -> bytes:
    if rng.random() < 0.3:
        extra = _choose_one(rng)
        combined = base + extra
        if len(combined) <= MAX_OUT:
            return combined
    return base

# Public API required by the harness

def generate(seed: int) -> bytes:
    rng = _rand_rng(seed)
    payload = _choose_one(rng)
    payload = _maybe_concat(rng, payload)
    # Ensure within size constraints
    if len(payload) > MAX_OUT:
        payload = payload[:MAX_OUT]
    return payload
